style.css:
@-moz-document domain("youtube.com") {
/* ✨ General Page Styling */
  body, ytd-app {
    background: url("https://i.pinimg.com/736x/04/ca/b6/04cab63c35ebe3666e744d9705e2eac3.jpg") repeat fixed center;
    background-size: cover;
    color: #fff;
    font-family: "Comic Sans MS", "Century Gothic", cursive !important;
  }

  /* ✨ Header Styling */
  #container.ytd-masthead, ytd-masthead {
    background: linear-gradient(to right, #ff66cc, #ff99cc) !important;
    border-bottom: 3px solid #fff0f5;
    box-shadow: 0 2px 10px hotpink;
  }

  /* ✨ Sidebar */
  ytd-guide-renderer {
    background: rgba(255, 192, 203, 0.8) !important;
    border-right: 2px dashed #fff;
  }

  /* ✨ Video Title Styling */
  h1.title, h1.ytd-video-primary-info-renderer,
  ytd-video-primary-info-renderer h1.title {
    color: #ffccff !important;
    text-shadow: 0 0 5px hotpink;
  }

  /* ✨ Buttons */
  ytd-toggle-button-renderer,
  tp-yt-paper-button {
    background: #ffc0cb !important;
    color: white !important;
    border-radius: 20px !important;
    font-weight: bold !important;
    border: 1px solid #fff !important;
  }

  /* ✨ Thumbnails Glow */
  ytd-thumbnail {
    border: 2px solid #ff69b4 !important;
    box-shadow: 0 0 10px #ff69b4;
    border-radius: 10px;
  }

  /* ✨ Scrollbar */
  ::-webkit-scrollbar {
    width: 12px;
  }
  ::-webkit-scrollbar-track {
    background: #ffe6f0;
  }
  ::-webkit-scrollbar-thumb {
    background: #ff66cc;
    border-radius: 6px;
  }

  /* ✨ Video Player Border */
  #player-container-outer {
    border: 4px double #ff69b4;
    box-shadow: 0 0 20px #ff99cc;
    border-radius: 10px;
  }

  /* ✨ Comments Section */
  #comments {
    background-color: rgba(255, 240, 245, 0.8) !important;
    border-radius: 10px;
    padding: 10px;
  }

  /* ✨ Pinkified Links */
  a {
    color: #ff66cc !important;
  }

  /* ✨ Like/Dislike Icons */
  ytd-toggle-button-renderer {
    filter: hue-rotate(300deg);
  }

  /* ✨ Gyaru Heart Cursor */
  * {
    cursor: url("https://www.cursor.cc/?"), auto !important;
  }
}
